/* GeoFlock: a short description of each capital, from the opening of its English Wikipedia article (CC BY-SA 4.0;
   each card links to the article). Shown on the card that opens from a star on the Capitals map. */
window.GF_CAPWIKI={"dz":{"t":"Algiers","x":"Algiers, officially Capital City of Algiers, is the capital and largest city of Algeria, located on the Mediterranean Sea in the north-central portion of the country. In 2025, an estimated 4.325 million people resided within the urban area."},"ao":{"t":"Luanda","x":"\nLuanda is the capital and largest city of Angola. It is Angola's primary port, and its major industrial, cultural and urban centre. Located on Angola's northern Atlantic coast, Luanda is Angola's administrative centre, its chief seaport, and also the capital of the Luanda Province."},"bj":{"t":"Porto-Novo","x":"Porto-Novo is the capital and second-largest city of Benin. The commune covers an area of 52 square kilometres (20 sq mi) and as of 2013 had a population of 264,320 people."},"bw":{"t":"Gaborone","x":"Gaborone is the capital and largest city of Botswana. It was formerly spelled as Gaberones during the colonial era, a name occasionally used in older English texts and maps. With a population of 246,325 based on the 2022 census, about 10% of the total population of Botswana."},"cm":{"t":"Yaoundé","x":"Yaoundé is the capital city of Cameroon. It has a population of more than 2.8 million, which makes it the second-largest city in the country after the port city Douala. It lies in the Centre Region of the nation at an elevation of about 750 metres (2,500 ft) above sea level."},"cv":{"t":"Praia","x":"Praia is the capital and largest city of Cape Verde. Located on the southern coast of Santiago island within the Sotavento Islands group, the city is the seat of the Praia Municipality. Praia is the political, economic and cultural center of Cape Verde."},"cg":{"t":"Brazzaville","x":"Brazzaville is the capital and largest city of the Republic of the Congo. Administratively, it is a department and a commune. Constituting the financial and administrative centre of the country, it is located on the north side of the Congo River, opposite Kinshasa, the capital city of the Democratic Republic of the Congo."},"cd":{"t":"Kinshasa","x":"Kinshasa, formerly named Léopoldville from 1881 to 1966, is the capital and largest city of the Democratic Republic of the Congo. Kinshasa is one of the world's fastest-growing megacities, with an estimated population of 18.5 million in 2026."},"dj":{"t":"Djibouti_City","x":"Djibouti City is the capital and largest city of the Republic of Djibouti. It is located in the coastal Djibouti Region on the Gulf of Tadjoura."},"eg":{"t":"Cairo","x":"Cairo is the capital and largest city of Egypt and the Cairo Governorate. It is home to more than 9.8 million people. The city is also part of the largest urban agglomeration in Africa, the Arab world, and the Middle East."},"gq":{"t":"Ciudad_de_la_Paz","x":"Ciudad de la Paz, previously known as Djibloho  or Oyala, commonly known as La Paz, is the official capital city of Equatorial Guinea, though it is still being built."},"er":{"t":"Asmara","x":"Asmara, or Asmera, is the capital and most populous city of Eritrea, in the country's Central Region. It sits at an elevation of 2,325 metres (7,628 ft), making it the sixth-highest capital in the world by altitude and the second-highest capital in Africa."},"sz":{"t":"Mbabane","x":"Mbabane is the most populous city in Eswatini, and is one of the two capitals, serving as the executive capital."},"et":{"t":"Addis_Ababa","x":"Addis Ababa is the capital and largest city of Ethiopia. With an estimated population of 6,287,000 inhabitants as of 2025, it is the tenth largest city in Africa. At an elevation of 2,355 metres (7,726 ft), it is the fourth-highest capital city in the world and the highest capital in Africa."},"ga":{"t":"Libreville","x":"Libreville is the capital and largest city of Gabon, located on the Gabon Estuary. Libreville occupies 65 square kilometres (25 sq mi) of the northwestern province of Estuaire. Libreville is also a port on the Gabon Estuary, near the Gulf of Guinea. As of the 2013 census, its population was 703,904."},"gm":{"t":"Banjul","x":"Banjul, officially the City of Banjul, is the capital city of the Gambia. The city of Banjul is located on St Mary's Island, which is in the Gambia River where it enters the Atlantic Ocean."},"gh":{"t":"Accra","x":"Accra is the capital and largest city of Ghana, located on the southern coast at the Gulf of Guinea, which is part of the Atlantic Ocean."},"gn":{"t":"Conakry","x":"Conakry is the capital and largest city of Guinea. A port city, it serves as the economic, financial and cultural centre of Guinea. Its population as of the 2025 Guinea census was 3,407,327, or around one-fifth of the country's population."},"gw":{"t":"Bissau","x":"Bissau is the capital and largest city of Guinea-Bissau. As of 2015, it had a population of 492,004. Bissau is located on the Geba River estuary, off the Atlantic Ocean, and is Guinea-Bissau's major port, as well as the country's administrative and military center."},"ke":{"t":"Nairobi","x":"Nairobi, is the capital and largest city of Kenya, located in the south-central part of the country. As of 2026, it has a population of 5.6 million and a metropolitan population of 15.95 million, making it the 8th most populous city in Africa and the 4th most populous metropolitan area."},"ls":{"t":"Maseru","x":"Maseru is the capital and largest city of Lesotho. It is also the capital of the Maseru District. Located on the Caledon River, Maseru lies directly on the Lesotho–South Africa border. Maseru had a population of 330,760 in the 2016 census."},"lr":{"t":"Monrovia","x":"Monrovia is the capital and largest city of the African country of Liberia. Founded in 1822, it is located on Cape Mesurado on the Atlantic coast and, as of the 2022 census, had a population of 1,761,032 residents."},"ly":{"t":"Tripoli,_Libya","x":"Tripoli, historically known as Tripoli-of-the-West, is the capital and largest city of Libya, with a population of about 3.246 million people in 2021. It is located in the northwest of Libya on the edge of the desert, on a point of rocky land projecting into the Mediterranean Sea and forming a bay."},"mg":{"t":"Antananarivo","x":"Antananarivo, also known by its colonial shorthand form Tana, is the capital and largest city of Madagascar. The administrative area of the city, known as Antananarivo-Renivohitra, is the capital of Analamanga region."},"mu":{"t":"Port_Louis","x":"Port Louis is the capital and most populous city of Mauritius, mainly located in the Port Louis District, with a small western part in the Black River District. Port Louis is the country's financial and political centre. It is administered by the Municipal City Council of Port Louis."},"ma":{"t":"Rabat","x":"Rabat is the capital city of Morocco, located on the northwestern coasts of the Atlantic Ocean. Rabat is the country's seventh-largest city with a population of 515,619 (2024) and the second largest metropolitan area after Casablanca, with a population of approximately 2.1 million (2025)."},"st":{"t":"São_Tomé","x":"São Tomé is the capital and largest city of the Central African island country of São Tomé and Príncipe. Its name is Portuguese for \"Saint Thomas\". Founded in the 15th century, it is one of Africa's oldest colonial cities."},"sl":{"t":"Freetown","x":"Freetown is the capital and largest city of Sierra Leone. It is a major port city on the Atlantic Ocean and is located in the Western Area of the country. Freetown is Sierra Leone's major urban, economic, financial, cultural, educational and political centre, as it is the seat of the Government of Sierra Leone."},"so":{"t":"Mogadishu","x":"Mogadishu, locally known as Xamar or Hamar, is the capital and most populous city of Somalia. The city has served as an important port connecting traders across the Indian Ocean for millennia and has an estimated urban population of 4,126,815."},"za":{"t":"Pretoria","x":"Pretoria is the executive capital of South Africa, serving as the seat of the executive branch of government, and as the host to all foreign embassies to the country."},"ss":{"t":"Juba","x":"Juba is the capital and largest city of South Sudan. The city is situated on the White Nile and also serves as the capital of the Central Equatoria State. It is the most recently declared national capital and had a population of 525,953 in 2017."},"sd":{"t":"Khartoum","x":"Khartoum, also spelled Khartum, is the capital and most populous city of Sudan as well as Khartoum State. With an estimated population of 7.1 million people, Greater Khartoum is the largest urban area in Sudan."},"tz":{"t":"Dodoma","x":"Dodoma, officially Dodoma City, is the capital city of Tanzania. With a population of 765,179 as of 2022 which is projected to reach 1,000,000 by the end of 2026, it is also the administrative capital of both Dodoma Municipal Council and the entire Dodoma Region."},"tg":{"t":"Lomé","x":"Lomé is the capital and largest city of Togo. It has an urban population of 837,437 while there were 2,188,376 permanent residents in its metropolitan area as of the 2022 census."},"tn":{"t":"Tunis","x":"Tunis is the capital and largest city of Tunisia. The greater metropolitan area of Tunis, often referred to as \"Grand Tunis\", has about 2,700,000 inhabitants. As of 2020, it was the third-largest city in the Maghreb region and the fifteenth-largest in the Arab world."},"ug":{"t":"Kampala","x":"Kampala is the capital and largest city of Uganda. The city proper has a population of 1,797,722 and is divided into the five political divisions of Kampala Central, Kawempe, Makindye, Nakawa, and Rubaga."},"zm":{"t":"Lusaka","x":"Lusaka is the capital and largest city of Zambia. It is one of the fastest-developing cities in southern Africa. Lusaka is in the southern part of the central plateau at an elevation of about 1,279 metres (4,196 ft). As of 2022, the city's population was approximately 2,204,059."},"zw":{"t":"Harare","x":"Harare is the capital and largest city of Zimbabwe. The city proper has an area of 982.3 km2 (379.3 sq mi), a population of 1,849,600 as of the 2022 census, and an estimated 2,487,209 people in its metropolitan province. The city is situated in north-eastern Zimbabwe in the country's Mashonaland region."},"af":{"t":"Kabul","x":"Kabul is the capital and largest city of Afghanistan. It is within the jurisdiction of Kabul District and has an estimated population of 5,333,284 people. Located in the eastern half of the country, forming part of the Kabul Province, the city is administratively divided into five zones and 22 municipal districts."},"am":{"t":"Yerevan","x":"Yerevan is the capital and largest city of Armenia, as well as one of the world's oldest continuously inhabited cities. Situated along the Hrazdan River, Yerevan is the administrative, cultural, and industrial centre of the country, as its primate city."},"az":{"t":"Baku","x":"Baku is the capital and largest city of Azerbaijan, as well as the largest city on the Caspian Sea and in the Caucasus region. Baku is 28 metres (92 ft) below sea level, which makes it the lowest lying national capital in the world and the largest city in the world below sea level."},"bh":{"t":"Manama","x":"Manama is the capital and largest city of Bahrain, with an approximate population of 743,066 as of the 2025 estimate. Long an important trading center in the Persian Gulf, Manama is home to a diverse population."},"bd":{"t":"Dhaka","x":"Dhaka, formerly spelled as Dacca, is the capital and largest city of Bangladesh. With an estimated population of 36.6 million, Dhaka is the second largest city by population in the world, and is widely considered to be the most densely populated built-up urban area in the world."},"bn":{"t":"Bandar_Seri_Begawan","x":"Bandar Seri Begawan (BSB) is the capital and largest city of Brunei. It is officially a municipal area with an area of 100.36 square kilometres (38.75 sq mi) and has a population of 72,133 as of 2025 estimate."},"kh":{"t":"Phnom_Penh","x":"Phnom Penh is the capital and most populous city of Cambodia. It has been the national capital since 1865 and has grown to become the nation's primate city and its political, economic, industrial, and cultural centre. The city's name derives from Wat Phnom, a Buddhist temple, and Lady Penh, the city's founder."},"cn":{"t":"Beijing","x":"Beijing, previously romanized as Peking, is the capital city of China. With more than 21.8 million residents, it is the world's most populous national capital city, as well as China's second-largest city by urban area, after Shanghai."},"cy":{"t":"Nicosia","x":"Nicosia, also known as Lefkosia or Lefkoşa, is the capital of Cyprus. It is the southeasternmost capital city among European Union member states. Its northern part is the de facto capital of Northern Cyprus."},"ge":{"t":"Tbilisi","x":"Tbilisi is the capital and largest city of Georgia, located on the banks of the Kura River. With more than 1.3 million inhabitants, it contains almost one third of the country's population."},"in":{"t":"New_Delhi","x":"New Delhi is a city and the capital city of India and a part of the National Capital Territory of Delhi (NCT). New Delhi is the seat of all three branches of the Government of India, hosting the Rashtrapati Bhavan, Sansad Bhavan, and the Supreme Court."},"id":{"t":"Jakarta","x":"Jakarta, officially the Special Capital Region of Jakarta, is the capital and largest city of Indonesia, with administrative status equivalent to a province. It lies on the northwestern coast of Java, bordering West Java and Banten and facing the Java Sea."},"ir":{"t":"Tehran","x":"Tehran is the capital and largest city of Iran. It is also the capital of Tehran province and the administrative center for Tehran County and its Central District."},"iq":{"t":"Baghdad","x":"Baghdad is the capital and the largest city of Iraq. It is located on the banks of the Tigris in central Iraq. With an estimated population of 8 million, it ranks among the most populous and largest cities in the Middle East and the Arab world and constitutes 22% of Iraq's population."},"il":{"t":"Jerusalem","x":"Jerusalem is a city in the Southern Levant, on a plateau in the Judaean Mountains between the Mediterranean and the Dead Sea. It is one of the oldest cities in the world and is considered a holy city to the three major Abrahamic religions: Judaism, Christianity and Islam."},"jp":{"t":"Tokyo","x":"Tokyo, officially the Tokyo Metropolis, is the capital and most populous city of Japan. The population of the city proper was over 14 million as of 2023."},"jo":{"t":"Amman","x":"Amman is the capital and the largest city of Jordan, and the country's economic, political, and cultural center."},"kz":{"t":"Astana","x":"Astana is the capital city of Kazakhstan. With a population of 1,7 million within the city limits, it is the second-largest in the country after Almaty, the national capital until 1997. The city lies on the banks of the Ishim river in the north of Kazakhstan and is located within the Akmola Region but is self-administering."},"kg":{"t":"Bishkek","x":"Bishkek, formerly known as Pishpek, and then Frunze (1926–1991), is the capital and largest city of Kyrgyzstan, and the capital of the Chüy Region. It is situated near the border with Kazakhstan and has a population of around 1,200,000 people as of 2024."},"la":{"t":"Vientiane","x":"Vientiane is the capital and largest city of Laos. Comprising the 5 urban districts of Vientiane Prefecture, the city is located on the banks of the Mekong, close to the border with Thailand. Vientiane was the administrative capital during French rule. The city had a population of 840,000 as of the 2023 census."},"lb":{"t":"Beirut","x":"Beirut is the capital and largest city of Lebanon. As of 2025, Greater Beirut has a population of 2.4 million, just under half of Lebanon's population, which makes it the twelfth-largest city in the Levant region and the sixteenth-largest in the Arab world."},"my":{"t":"Kuala_Lumpur","x":"Kuala Lumpur (KL), officially the Federal Territory of Kuala Lumpur, is the capital city and a federal territory of Malaysia. It is the most populous city in the country, covering an area of 243 km2 (94 sq mi) with a population of 2,111,536 as of 2026."},"mn":{"t":"Ulaanbaatar","x":"Ulaanbaatar is the capital and largest city of Mongolia. It has a population of 1.79 million, and is the coldest capital city in the world by average yearly temperature. The municipality is located in north central Mongolia at an elevation of about 1,300 metres (4,300 ft) in a valley on the Tuul River."},"mm":{"t":"Naypyidaw","x":"Naypyidaw, officially romanised as Nay Pyi Taw (NPT), is the capital and third-largest city of Myanmar. The city is located at the centre of the Naypyidaw Union Territory. It is unusual among Myanmar's cities in that it is an entirely planned city and not part of any state or region."},"np":{"t":"Kathmandu","x":"Kathmandu is the capital and largest city of Nepal, situated in the central part of the country within the Kathmandu Valley. The city is in Kathmandu District. Kathmandu is the main governmental, financial, industrial, and cultural centre of Nepal."},"kp":{"t":"Pyongyang","x":"Pyongyang (Korean: 평양) is the capital and largest city of North Korea. According to the 2008 population census, it has a population of 3,255,288. Pyongyang is located on the Taedong River about 109 kilometers upstream from its mouth on the Yellow Sea."},"om":{"t":"Muscat","x":"Muscat is the capital and most populous city of Oman. It is the seat of the Governorate of Muscat. According to the National Centre for Statistics and Information (NCSI), the population of the Muscat Governorate in 2022 was 1.72 million."},"ps":{"t":"Ramallah","x":"Ramallah is a city in the central West Bank, Palestine. It serves as the administrative capital of Palestine, as well as capital of the Ramallah and al-Bireh Governorate. The city is situated on the Judaean Mountains, 10 km north of Jerusalem, at an average elevation of 872 meters (2,861 ft) above sea level, adjacent to al-Bireh."},"pk":{"t":"Islamabad","x":"Islamabad is the capital city of Pakistan. It is the country's tenth-most populous city with a population of over 1.1 million and is federally administered by the Pakistani government as part of the Islamabad Capital Territory — with a metropolitan population of over 2.3 million."},"ph":{"t":"Manila","x":"Manila, officially the City of Manila, is the capital and second-most populous city of the Philippines after Quezon City. According to the 2024 census, it has a population of 1,902,590 people. Located on the eastern shore of Manila Bay on the island of Luzon, it is classified as a highly urbanized city."},"qa":{"t":"Doha","x":"Doha is the capital and largest city, and main financial hub of Qatar. Located on the Persian Gulf coast in the east of the country, north of Al Wakrah and south of Al Khor and Lusail, it is home to most of the country's population."},"sa":{"t":"Riyadh","x":"Riyadh is the capital and largest city of Saudi Arabia, as well as the largest city on the Arabian Peninsula. It serves as the administrative capital of both the Riyadh Province and the Riyadh Emirate."},"sg":{"t":"Singapore","x":"Singapore, officially the Republic of Singapore, is an island country in Southeast Asia. Its territory comprises a main island, over 60 satellite islands and islets, and one outlying islet."},"kr":{"t":"Seoul","x":"Seoul, officially Seoul Special Metropolitan City, is the capital and largest city of South Korea, and the largest city in the whole of Korea."},"tj":{"t":"Dushanbe","x":"Dushanbe is the capital and largest city of Tajikistan. As of February 2023, Dushanbe had a population of 1,228,400, with this population being largely Tajik. Until 1929, the city was known in Russian as Dyushambe, and from 1929 to 1961 as Stalinabad, after Joseph Stalin."},"th":{"t":"Bangkok","x":"Bangkok, known in Thai as Krung Thep Maha Nakhon and colloquially as Krung Thep, is the capital and largest city of Thailand."},"tl":{"t":"Dili","x":"Dili is the capital and largest city of Timor-Leste. It lies on the northern coast of the island of Timor, in a small area of flat land hemmed in by mountains. The climate is tropical with distinct wet and dry seasons."},"tr":{"t":"Ankara","x":"Ankara is the capital city of Turkey. Located in the central part of Anatolia, the city has a population of over 5.3 million residents in its urban center, out of 6 million residents in Ankara Province. Ankara is Turkey's second-largest city by population after Istanbul."},"tm":{"t":"Ashgabat","x":"Ashgabat is the capital and largest city of Turkmenistan. It lies between the Karakum Desert and the Köpetdag mountain range in Central Asia, approximately 50 km (30 mi) away from the Iran-Turkmenistan border. The city has a population of 1,030,063."},"ae":{"t":"Abu_Dhabi","x":"Abu Dhabi is the capital city of the United Arab Emirates (UAE), and of the Emirate of Abu Dhabi, the seat of the Abu Dhabi Central Capital District and the UAE's second-most populous city, after Dubai. Situated on a T-shaped island, Abu Dhabi extends into the Persian Gulf from the central-western coast of the UAE."},"uz":{"t":"Tashkent","x":"Tashkent, also spelled Toshkent, is the capital and largest city of Uzbekistan. It is the most populous city in Central Asia, with a population of more than 3.1 million people as of July 1, 2025. It is located in northeastern Uzbekistan."},"vn":{"t":"Hanoi","x":"Hanoi is the capital and second-most populous centrally-governed city of Vietnam. It covers an area of 3,358.6 km2 (1,296.8 mi2), and as of 2026 has a population of 8.7 million."},"al":{"t":"Tirana","x":"Tirana is the capital and largest city of Albania. It is located in the centre of the country, enclosed by mountains and hills, with Dajti rising to the east and a slight valley to the northwest overlooking the Adriatic Sea in the distance. It is among the wettest and sunniest cities in Europe, with 2,544 hours of sun per year."},"ad":{"t":"Andorra_la_Vella","x":"Andorra la Vella is the capital and largest city of Andorra. It is located high in the east Pyrenees, between France and Spain. It is also the name of the Andorran parish that surrounds the capital."},"at":{"t":"Vienna","x":"Vienna is the capital, most populous city, and one of the nine states of Austria. It is Austria's primate city, with just over two million inhabitants. Its larger metropolitan area has a population of nearly 2.9 million, representing nearly one-third of the country's population."},"by":{"t":"Minsk","x":"Minsk is the capital and largest city of Belarus, located on the Svislach and the now subterranean Nyamiha rivers. As the capital, Minsk has a special administrative status in Belarus and is the administrative centre of Minsk region and Minsk district."},"be":{"t":"Brussels","x":"Brussels, officially the Brussels-Capital Region, is a region of Belgium comprising 19 municipalities, including the City of Brussels, which is the capital of Belgium. The Brussels-Capital Region is located in the central portion of the country."},"ba":{"t":"Sarajevo","x":"Sarajevo is the capital and largest city of Bosnia and Herzegovina, with a population of 275,524 in its administrative limits. The Sarajevo Canton, containing the city of Sarajevo and nearby municipalities, is home to 413,593 inhabitants."},"bg":{"t":"Sofia","x":"Sofia is the capital and largest city of Bulgaria. It is situated in the Sofia Valley at the foot of the Vitosha mountain, in the western part of the country. The city is built west of the Iskar river and has many mineral springs, such as the Sofia Central Mineral Baths. It has a humid continental climate."},"hr":{"t":"Zagreb","x":"Zagreb is the capital and largest city of Croatia. It is in the north of the country, along the Sava River, at the southern slopes of the Medvednica mountain. Zagreb stands near the international border between Croatia and Slovenia at an elevation of approximately 158 m (518 ft) above sea level."},"cz":{"t":"Prague","x":"Prague is the capital and largest city of the Czech Republic and the historical capital of Bohemia. Located on the Vltava River, the city has a population of about 1.4 million, making it the twelfth-largest city in the European Union. Its metropolitan area is home to approximately 2.3 million people."},"dk":{"t":"Copenhagen","x":"Copenhagen is the capital and most populous city of Denmark, with an urban population of 1.4 million. The city is situated mainly on the island of Zealand (Sjælland), with a smaller part on the island of Amager. Copenhagen is separated from Malmö, Sweden, by the Øresund strait."},"ee":{"t":"Tallinn","x":"Tallinn is the capital and largest city of Estonia. Located on a bay in northern Estonia, on the shore of the Gulf of Finland of the Baltic Sea, it has a population of 452,563 as of 2026, making it the third most-populous city in the Baltics. As of 2024, the population of the Tallinn metropolitan area is estimated at 646,315."},"fi":{"t":"Helsinki","x":"Helsinki, until about 1930 known in English by its Swedish name of Helsingfors, is the capital and most populous city in Finland. It is on the shore of the Gulf of Finland and is the seat of southern Finland's Uusimaa region."},"fr":{"t":"Paris","x":"Paris is the capital and largest city of France, with an estimated city population of 2.04 million in an area of 105.4 km2 (40.7 sq mi), as of January 2026, and a metropolitan population of 13.3 million (2023)."},"de":{"t":"Berlin","x":"Berlin is the capital and largest city of Germany. With 3.7 million inhabitants, it has the highest population within its city limits of any city in the European Union (EU). The metropolis is also one of the states of Germany, being the third-smallest state in the country by area."},"gr":{"t":"Athens","x":"Athens is the capital and largest city of Greece. A significant coastal urban area in the Mediterranean, Athens is also the capital of the Attica region and is the southernmost capital on the European mainland."},"hu":{"t":"Budapest","x":"Budapest is the capital and largest city of Hungary. It is Hungary's primate city with 1.7 million inhabitants and its greater metro area has a population of about 3.3 million, representing one-third of the country's population and producing more than 40% of the country's economic output."},"is":{"t":"Reykjavík","x":"Reykjavík is the capital and largest city of Iceland. It is located on the southern shore of the Faxaflói bay in southwest Iceland and has a latitude of 64°08′ N, making it the world's northernmost capital of a sovereign state."},"ie":{"t":"Dublin","x":"Dublin is the capital and largest city of Ireland. Situated on Dublin Bay at the mouth of the River Liffey, it is in the province of Leinster, and is bordered on the south by the Dublin Mountains, part of the Wicklow Mountains range."},"it":{"t":"Rome","x":"Rome is the capital and largest city of Italy. It is also the administrative centre of the Lazio region and of the Metropolitan City of Rome."},"lv":{"t":"Riga","x":"Riga, officially Riga State City, is the capital, primate, and largest city of Latvia and the second most-populous city in the Baltics. Home to 588,911 inhabitants, the city accounts for a third of Latvia's total population. The population of Riga metropolitan area, which stretches beyond the city limits, is estimated at 847,162."},"li":{"t":"Vaduz","x":"Vaduz is the capital of Liechtenstein and also the seat of the national parliament. The town, which is located along the Rhine, has 5,696 residents. The most prominent landmark of Vaduz is Vaduz Castle, perched atop a steep hill overlooking the town."},"lt":{"t":"Vilnius","x":"Vilnius is the capital and largest city of Lithuania and the most-populous city in the Baltic states. The city's estimated July 2026 population was 619,405, and the Vilnius urban area has an estimated population of 767,907."},"lu":{"t":"Luxembourg_City","x":"Luxembourg, also known as Luxembourg City, is the capital city of the Grand Duchy of Luxembourg and the country's most populous commune."},"mt":{"t":"Valletta","x":"Valletta, also known as Città Umilissima, is the capital city of Malta and one of its 68 council areas. Located between the Grand Harbour to the east and Marsamxett Harbour to the west, its population as of 2021 was 5,157. As Malta's capital city, it is a commercial centre for shopping, bars, dining, and café life."},"md":{"t":"Chișinău","x":"Chișinău is the capital and largest city of Moldova by area and population. The city is Moldova's main industrial and commercial centre. It is situated in the middle of the country, on the river Bîc, a tributary of the Dniester."},"mc":{"t":"Monaco","x":"Monaco, officially the Principality of Monaco, is a sovereign city-state and microstate in Western Europe. Situated on the French Riviera, it is a semi-enclave bordered by France to the north, east, and west, with the Mediterranean Sea to the south; the Italian region of Liguria is about 15 km (9.3 mi) east."},"nl":{"t":"Amsterdam","x":"Amsterdam is the capital and largest city of the Netherlands. As of 1 January 2026, it had a population of 941,873 within the city proper, 1,457,018 in the urban area and 2,480,394 in the metropolitan area."},"mk":{"t":"Skopje","x":"Skopje is the capital and largest city of North Macedonia. It lies in the northern part of the country, in the Skopje Valley along the Vardar River, and is the political, economic, and cultural centre of the country. As of the 2021 census, the city had a population of 526,502."},"no":{"t":"Oslo","x":"Oslo is the capital and largest city of Norway. It constitutes both a county and a municipality. The municipality of Oslo had a population of 724,290 in 2025, while the city's greater urban area had a population of 1,110,887 in 2025, and the metropolitan area had an estimated population of 1,546,706 in 2021."},"pl":{"t":"Warsaw","x":"Warsaw, officially the Capital City of Warsaw, is the capital and most populous city of Poland. The metropolis stands on the river Vistula in east-central Poland."},"pt":{"t":"Lisbon","x":"Lisbon is the capital and most populous city of Portugal, with an estimated population of 658,236 as of 2025, within its administrative limits and 3,353,000 within the metropolis, as of 2025. The city lies in the western part of the Iberian Peninsula, fronting the northern shore of the River Tagus."},"ro":{"t":"Bucharest","x":"Bucharest is the capital and largest city of Romania. The metropolis stands on the River Dâmbovița in south-eastern Romania. Its population is officially estimated at 1.71 million residents within a greater metropolitan area of 2.33 million residents, which makes Bucharest the fifteenth-largest city in Europe."},"ru":{"t":"Moscow","x":"Moscow is the capital and largest city of Russia, situated on the Moskva River in Central Russia. The city has a population estimated at more than 13 million residents within city limits, more than 19.1 million residents in the urban area, and more than 21.5 million residents in the metropolitan area."},"sm":{"t":"San_Marino","x":"San Marino, officially the Republic of San Marino, is a landlocked country in Southern Europe, completely surrounded by Italy. Located on the northeastern slopes of the Apennine Mountains, it is the larger of two microstates within the Italian Peninsula, the other being Vatican City."},"rs":{"t":"Belgrade","x":"Belgrade is the capital and largest city of Serbia. It is located at the confluence of the Sava and Danube rivers and at the crossroads of the Pannonian Plain and the Balkan Peninsula."},"sk":{"t":"Bratislava","x":"Bratislava is the capital and largest city of Slovakia and the fourth largest of all cities on the river Danube. Officially, the population of the city proper is about 479,000, with the wider Bratislava Region exceeding 732,000 inhabitants. The metropolitan area has a population of approximately 1.3 million."},"si":{"t":"Ljubljana","x":"Ljubljana is the capital and largest city of Slovenia, located along a trade route between the northern Adriatic Sea and the Danube region, north of the country's largest marsh; it has been inhabited since prehistoric times."},"es":{"t":"Madrid","x":"Madrid is the capital and largest city of Spain. It had a population of over 3.4 million in the city proper in 2025, and a metropolitan area population of approximately 6.8 million. Madrid is the second-largest city in the European Union (EU), after Berlin, and its metropolitan area is the second-largest in the EU, after Paris."},"se":{"t":"Stockholm","x":"Stockholm is the capital and most populous city of Sweden, as well as the largest urban area in the Nordic countries. Approximately 1 million people live in the municipality, with 1.6 million in the urban area, and 2.5 million in the metropolitan area."},"ch":{"t":"Bern","x":"Bern, or Berne, is the de facto capital of Switzerland, referred to as the \"federal city\". With a population of about 146,000, Bern is the fifth-most populous city in Switzerland, behind Zurich, Geneva, Basel and Lausanne. The Bern agglomeration, which includes 36 municipalities, had a population of 406,900 in 2014."},"ua":{"t":"Kyiv","x":"Kyiv, also spelt Kiev, is the capital and most populous city of Ukraine. Located in the north-central part of the country, it straddles both banks of the Dnieper River. As of January 2022, the population of Kyiv was 2,952,301, making it the seventh-most populous city in Europe."},"gb":{"t":"London","x":"London is the capital and largest city of England and the United Kingdom, with a population of 9.14 million people in 2025. Its wider metropolitan area is the largest in Western Europe, with a population of 15.4 million."},"va":{"t":"Vatican_City","x":"Vatican City, officially the Vatican City State, is a landlocked sovereign city-state in Southern Europe. Ruled by the pope, it is an enclave within the city of Rome, Italy, and serves as the administrative center of the Catholic Church."},"xk":{"t":"Pristina","x":"Pristina is the capital and largest city of Kosovo. It is the administrative center of the eponymous municipality and district."},"ag":{"t":"St._John's,_Antigua_and_Barbuda","x":"St. John's is the largest city in Antigua and Barbuda. It is located in the western part of Antigua, surrounding St. John's Harbour. It is the main city of the Central Plain region. The city is Antigua and Barbuda's primate city, having a population of 22,219. St."},"ar":{"t":"Buenos_Aires","x":"Buenos Aires, officially the Autonomous City of Buenos Aires, is the capital and largest city of Argentina. It is located on the southwest of the Río de la Plata. Buenos Aires is classified as an Alpha− global city, according to the GaWC 2024 ranking."},"bs":{"t":"Nassau,_Bahamas","x":"Nassau is the capital and largest city of the Bahamas. It is on the island of New Providence, which has a population of 296,522, 74.26% of the country's total population. Nassau is commonly defined as a primate city, dwarfing all other towns in the country."},"bo":{"t":"Sucre","x":"Sucre, officially La Ilustre y Heroica Sucre is the de jure capital city of Bolivia, the capital of the Chuquisaca Department and the sixth most populous city in Bolivia."},"br":{"t":"Brasília","x":"Brasília is the capital city of Brazil and the Federal District. Located in the Brazilian Highlands in the country's Central-West region, it was founded by President Juscelino Kubitschek on 21 April 1960, to replace Rio de Janeiro as the national capital."},"ca":{"t":"Ottawa","x":"Ottawa is the capital city of Canada. It is located in the southeastern portion of the province of Ontario, at the confluence of the Ottawa River and the Rideau River. Ottawa borders Gatineau, Quebec, and forms the core of the Ottawa–Gatineau census metropolitan area (CMA) and the National Capital Region (NCR)."},"cl":{"t":"Santiago","x":"Santiago, also known as Santiago de Chile, is the capital and largest city of Chile and one of the largest cities in the Americas."},"co":{"t":"Bogotá","x":"Bogotá is the capital and largest city of Colombia. The city is administered as the Capital District, as well as the capital of, though not politically part of, the surrounding department of Cundinamarca. Bogotá is a territorial entity of the first order, with the same administrative status as the departments of Colombia."},"cu":{"t":"Havana","x":"Havana is the capital and largest city of Cuba. The heart of La Habana Province, Havana is the country's main port and commercial center. It is the most populous city, the largest by area, and the second-largest metropolitan area in the Caribbean region."},"dm":{"t":"Roseau","x":"Roseau is the capital and largest city of Dominica, with a population of 14,725 as of 2011. It is a small and compact urban settlement, in the Saint George parish and surrounded by the Caribbean Sea, the Roseau River and Morne Bruce."},"do":{"t":"Santo_Domingo","x":"Santo Domingo, officially known as Santo Domingo de Guzmán, is the capital and largest city of the Dominican Republic and the largest metropolitan area in the Caribbean by population. As of 2022, the city center had a population of 1,029,110 while its metropolitan area, Greater Santo Domingo, had a population of 4,274,651."},"ec":{"t":"Quito","x":"Quito, officially San Francisco de Quito, is the capital of Ecuador, and the province of Pichincha. It is the largest city in Pichincha and the second-largest city in Ecuador, with an estimated population of 1.7 million in the city and 2.8 million in its metropolitan area."},"sv":{"t":"San_Salvador","x":"San Salvador is the capital and largest city of El Salvador and of its eponymous department. It is the country's largest agglomeration, serving as the country's political, cultural, educational and financial center. The municipality of San Salvador has 525,990 inhabitants (2024)."},"gt":{"t":"Guatemala_City","x":"Guatemala City, also known colloquially by the nickname Guate, is the national capital and largest city of the Republic of Guatemala. It serves as the municipal capital of the surrounding Guatemala Department. Its metropolitan area is also the largest in Central America."},"gy":{"t":"Georgetown,_Guyana","x":"Georgetown is the capital and largest city of Guyana. It is situated in Demerara-Mahaica, region 4, on the Atlantic Ocean coast, at the mouth of the Demerara River. It is nicknamed the \"Garden City of the Caribbean\"."},"ht":{"t":"Port-au-Prince","x":"Port-au-Prince is the capital and most populous city of Haiti. The city's population was estimated at 1,200,000 in 2022 with the metropolitan area estimated at a population of 2,618,894."},"hn":{"t":"Tegucigalpa","x":"Tegucigalpa —formally Tegucigalpa, Municipality of the Central District, and colloquially referred to as Tegus, Teguz or Cerrocigalpa —is the capital and largest city of Honduras along with its sister city, Comayagüela."},"jm":{"t":"Kingston,_Jamaica","x":"Kingston is the capital and largest city of Jamaica, located on the southeastern coast of the island. It faces a natural harbour protected by the Palisadoes, a long sand spit which connects the town of Port Royal and Norman Manley International Airport to the rest of the island."},"mx":{"t":"Mexico_City","x":"Mexico City is the capital and largest city of Mexico, as well as the most populous city in North America. It is one of the world's leading cultural and financial centers and, according to the Globalization and World Cities Research Network's 2024 ranking, is classified as an Alpha world city."},"ni":{"t":"Managua","x":"Managua is the capital and largest city of Nicaragua, and one of the largest cities in Central America. Located on the shores of Lake Managua, the city had an estimated population of 1,063,815 as of 2023, and a population of 1,401,687 in its metropolitan area. The city also serves as the seat of Managua Department."},"pa":{"t":"Panama_City","x":"Panama City, also known as Panama, is the capital and largest city of the Republic of Panama. It has a total population of 410,354 in the city proper and 1,086,990 in the Panamá District, which includes the outer corregimientos of the city. The metropolitan area has over 2,100,000 people."},"py":{"t":"Asunción","x":"Asunción is the capital and the largest city of Paraguay. The city lies on the eastern bank of the Paraguay River, immediately north northeast of the confluence where it is joined by the Pilcomayo River."},"pe":{"t":"Lima","x":"Lima is the capital and largest city of Peru, as well as a primate city. It is located in the valleys of the Chillón, Rímac and Lurín Rivers, in the desert zone of the central coastal part of the country, overlooking the Pacific Ocean. The city is considered the political, cultural, financial and commercial center of Peru."},"lc":{"t":"Castries","x":"Castries is the capital and largest city of Saint Lucia, an island country in the Caribbean. The urban area has a population of approximately 20,000, while the eponymous district has a population of just under 70,000, as of May 2013. The city covers 80 km2 (31 sq mi)."},"vc":{"t":"Kingstown","x":"Kingstown is the capital and largest city of Saint Vincent and the Grenadines. The city, located on the main island of Saint Vincent, has the main port and the biggest commercial center of the islands. With a population of 12,909 (2012), Kingstown is the most populous settlement in the country."},"sr":{"t":"Paramaribo","x":"Paramaribo, locally nicknamed Foto, is the capital and largest city of Suriname, located on the banks of the Suriname River in the Paramaribo District. Paramaribo has a population of roughly 252,581 people as of the 2025 estimate, almost half of Suriname's population."},"tt":{"t":"Port_of_Spain","x":"Port of Spain is the capital and chief port of Trinidad and Tobago. With a municipal population of 49,867 (2017), an urban population of 81,142 and a transient daily population of 250,000, it is Trinidad and Tobago's third largest municipality, after Chaguanas and San Fernando."},"us":{"t":"Washington,_D.C.","x":"Washington, D.C., officially the District of Columbia and commonly shortened to Washington, or DC, is the capital city of the United States, and its only federal district."},"uy":{"t":"Montevideo","x":"Montevideo is the capital and largest city of Uruguay. As of the 2023 census, the city proper has a population of 1,287,452, making up about 36.8% of the country's total population, in an area of 201 square kilometers (78 sq mi)."},"ve":{"t":"Caracas","x":"Caracas, officially Santiago de León de Caracas (CCS), is the capital and largest city of Venezuela, and the center of the Metropolitan Region of Caracas. It is located along the Guaire River in the northern part of Venezuela, within the Caracas Valley of the Venezuelan coastal mountain range."},"au":{"t":"Canberra","x":"Canberra is the capital city of Australia and the largest population centre in the Australian Capital Territory. With an estimated population of 484,630 as of 2025, Canberra is Australia's largest inland city and the eighth-largest Australian city by population."},"fj":{"t":"Suva","x":"Suva is the capital and most populous settlement of Fiji. It is the centre of Fiji's largest metropolitan area and serves as its major port. The city is on the southeast coast of the island of Viti Levu, in Rewa Province, Central Division."},"ki":{"t":"South_Tarawa","x":"South Tarawa is the capital and hub of the Republic of Kiribati and home to more than half of Kiribati's population."},"mh":{"t":"Majuro","x":"Majuro is the capital and largest city of the Marshall Islands. It is also a large coral atoll of 64 islands in the Pacific Ocean. It forms a legislative district of the Ratak (Sunrise) Chain of the Marshall Islands."},"nz":{"t":"Wellington","x":"Wellington is the capital city of New Zealand. It is located at the southwestern tip of the North Island, between Cook Strait and the Remutaka Range. Wellington is the third-largest city in New Zealand, and is the administrative centre of the Wellington Region. It is the world's southernmost capital of a sovereign state."},"pw":{"t":"Ngerulmud","x":"Ngerulmud is the seat of government of the Republic of Palau, an island nation in the Pacific Ocean. It replaced Koror City as the capital in October 2006."},"pg":{"t":"Port_Moresby","x":"Port Moresby, also referred to as Pom City or simply Moresby, is the capital and largest city of Papua New Guinea. It is one of the largest cities in the southwestern Pacific outside of Australia and New Zealand."},"sb":{"t":"Honiara","x":"Honiara is the capital and largest city of Solomon Islands, situated on the northwestern coast of Guadalcanal. As of 2019, it had a population of 129,569 people. The city is served by Honiara International Airport and the seaport of Point Cruz, and lies along the Kukum Highway."},"tv":{"t":"Funafuti","x":"Funafuti is an atoll, comprising numerous islets, that is the capital of Tuvalu. As of the 2017 census, it has a population of 6,320 people. More people live in Funafuti than the rest of Tuvalu combined, with it containing approximately 60% of the nation's population. It is the world's easternmost capital of a sovereign state."},"vu":{"t":"Port_Vila","x":"Port Vila, or simply Vila, is the capital of Vanuatu and its largest city. It is on the island of Efate, in Shefa Province. The population was 49,034 as of the 2020 Vanuatu census. This represented 16.3% of Vanuatu's total population in 2020."},"mp":{"t":"Saipan,_Northern_Mariana_Islands","x":"Saipan is the largest island and capital of the Northern Mariana Islands, an unincorporated territory of the United States in the western Pacific Ocean. According to 2020 estimates by the United States Census Bureau, the population of Saipan was 43,385. Its people have been United States citizens since the 1980s."},"pn":{"t":"Adamstown,_Pitcairn_Islands","x":"Adamstown is the capital and only settlement of the Pitcairn Islands, the only British Overseas Territory that is located in the southern Pacific Ocean."},"pm":{"t":"Saint-Pierre,_Saint_Pierre_and_Miquelon","x":"Saint-Pierre is the capital of the French collectivité d'outre-mer (territory) of Saint Pierre and Miquelon, off the coast of the Canadian island of Newfoundland. Saint-Pierre is the more populous of the two communes (municipalities) making up Saint Pierre and Miquelon."},"hk":{"t":"Hong_Kong","x":"Hong Kong is a special administrative region of China. Situated on China's southern coast just south of Shenzhen, it consists of Hong Kong Island, Kowloon, and the New Territories. With 7.5 million residents in a 1,114-square-kilometre (430 sq mi) territory, Hong Kong is the fourth-most densely populated region in the world."},"mo":{"t":"Macau","x":"Macau or Macao is a special administrative region of China. It consists of the Macau Peninsula, the islands of Taipa and Coloane, the Cotai reclamation zone between Taipa and Coloane, and several smaller islets. It borders Zhuhai to the north and west, and it lies west of Hong Kong, separated by the Pearl River estuary."},"tw":{"t":"Taipei","x":"Taipei, officially Taipei City, is the capital and a special municipality of Taiwan. Located in Northern Taiwan, Taipei City is an enclave of the municipality of New Taipei City that sits about 25 kilometres (16 mi) southwest of the northern port city of Keelung. Most of the city rests on the Taipei Basin, an ancient lakebed."},"tdr":{"t":"Tiraspol","x":"Tiraspol is the capital and largest city of Transnistria, a breakaway state of Moldova, where it is the second-largest city. The city is located on the eastern bank of the Dniester River. Tiraspol is a regional hub of culture, economy, tourism, and light industry, such as furniture and electrical goods production."},"gi":{"t":"Gibraltar","x":"Gibraltar is a British Overseas Territory and city located near the southern tip of the Iberian Peninsula, on the Bay of Gibraltar, near the exit of the Mediterranean Sea into the Atlantic Ocean. It has an area of 6.8 km2 (2.6 sq mi) and is bordered to the north by Spain."},"aw":{"t":"Oranjestad","x":"Oranjestad, the capital and most populous of Aruba's eight regions, is located on the southwestern coast of the island."},"cw":{"t":"Willemstad","x":"Willemstad is the capital and largest city of Curaçao, an island in the southern Caribbean Sea that is a constituent country of the Kingdom of the Netherlands. It was the capital of the Netherlands Antilles prior to that entity's dissolution in 2010."},"ax":{"t":"Mariehamn","x":"Mariehamn is the capital of Åland, an autonomous region of Finland, and the seat of its government and parliament."},"sj":{"t":"Longyearbyen","x":"Longyearbyen is one of the world's northernmost settlements, with an estimated population of around 2,400–2,800, and is the capital and largest settled area of Svalbard."},"as":{"t":"Pago_Pago,_American_Samoa","x":"Pago Pago is the capital of American Samoa. It is in Maoputasi County on Tutuila, the main island of American Samoa."},"ky":{"t":"George_Town,_Cayman_Islands","x":"George Town is the capital and largest city in the Cayman Islands, located on Grand Cayman. It was named after King George III. As of 2025, the city had a population of 47,009, making it the largest city of all the British Overseas Territories."},"im":{"t":"Douglas,_Isle_of_Man","x":"Douglas is a port city and the capital of the Isle of Man, situated on the Douglas Bay, near the Irish Sea. It is located at the mouth of the River Douglas, and on a sweeping bay of two miles. The River Douglas forms part of the city's harbour and main commercial port."},"bi":{"t":"Gitega","x":"Gitega, formerly Kitega, is the political capital of Burundi."},"cf":{"t":"Bangui","x":"Bangui is the capital and largest city of the Central African Republic."},"ci":{"t":"Yamoussoukro","x":"Yamoussoukro is the capital city of Ivory Coast and an autonomous district. As of the 2014 census, Yamoussoukro is the third most populous city in the Ivory Coast, with a population of 361,893."},"mw":{"t":"Lilongwe","x":"Lilongwe is the capital and largest city of Malawi. It has a population of 989,318 as of the 2018 Census, up from a population of 674,448 in 2008. In 2020, that figure was 1,122,000."},"ml":{"t":"Bamako","x":"Bamako is the capital and largest city of Mali with a 2022 population of 4,227,569. It is located on the Niger River, near the rapids that divide the upper and middle Niger valleys in the southwestern part of the country, and the city is surrounded on all sides by the Koulikoro Region."},"mz":{"t":"Maputo","x":"Maputo is the capital and largest city of Mozambique. Located near the southern end of the country, it is within 120 kilometres of the borders with Eswatini and South Africa. The city has a population of 1,088,449 distributed over a land area of 347.69 km2 (134.24 sq mi)."},"na":{"t":"Windhoek","x":"Windhoek is the capital and largest city of Namibia. It is located in central Namibia on the Khomas Highland plateau area, at around 1,700 m (5,600 ft) above sea level in the geographical centre of the country. The population was 486,186 in 2023, and growing, due to migration from other regions in Namibia."},"ne":{"t":"Niamey","x":"Niamey is the capital and largest city of Niger. It is in the western part of the country, surrounded by the Tillabéri Region. Niamey lies on the Niger River, primarily situated on the river's left bank. The capital of Niger since the colonial era, Niamey is an ethnically diverse city and the country's main economic centre."},"ng":{"t":"Abuja","x":"Abuja is the capital city of Nigeria, strategically situated at the geographic midpoint of the country within the Federal Capital Territory (FCT). As the seat of the Federal Government of Nigeria, it hosts key national institutions, landmarks, and buildings spread across its over 50 districts."},"sn":{"t":"Dakar","x":"Dakar is the capital and largest city of Senegal. The department of Dakar has a population of 1,278,469, and the population of the Dakar metropolitan area was at 4.0 million in 2023."},"sc":{"t":"Victoria,_Seychelles","x":"Victoria is the capital and largest city of Seychelles, situated on the north-eastern side of Mahé, the archipelago's main island. The city was first established as the seat of the British colonial government."},"bt":{"t":"Thimphu","x":"Thimphu is the capital and largest city of Bhutan. It is situated in the western central part of Bhutan, and the surrounding valley is one of Bhutan's dzongkhags, the Thimphu District."},"mv":{"t":"Malé","x":"Malé is the capital and most populous city of the Maldives. With a population of 211,908 in 2022 within its administrative area and coterminous geographical area of 1.9 square kilometres (0.73 sq mi), Malé is one of the most densely populated cities in the world."},"lk":{"t":"Sri_Jayawardenepura_Kotte","x":"Sri Jayawardenepura Kotte, also known as Kotte, is the legislative capital city of Sri Lanka. Sri Jayawardenepura Kotte is located adjacent to the urban area of Sri Lanka's de facto economic capital, Colombo."},"sy":{"t":"Damascus","x":"Damascus is the capital and largest city of Syria. It is the oldest capital city in the world. Known colloquially in Syria as aš-Šām and dubbed, poetically, the \"City of Jasmine\", Damascus is a major cultural center of the Levant and the Arab world."},"ye":{"t":"Sanaa","x":"Sanaa, officially the Sanaa Municipality, is the capital and largest city of Yemen. The city is the capital of the Sanaa Governorate, but is not part of the governorate, as it forms a separate administrative unit."},"me":{"t":"Podgorica","x":"Podgorica is the capital and largest city of Montenegro. The city is located in central Montenegro, at the confluence of Ribnica and Morača rivers, where the southern foothills of Dinaric Alps meet the northernmost part of Zeta Plain."},"bb":{"t":"Bridgetown","x":"Bridgetown is the capital and largest city of Barbados. Formerly The Town of Saint Michael, the Greater Bridgetown area is located within the parish of Saint Michael. Bridgetown is sometimes locally referred to as \"The City\", but the most common reference is simply \"Town\"."},"bz":{"t":"Belmopan","x":"Belmopan is the capital city of Belize. Its population in 2022 was 20,754. Belmopan is the smallest capital city in the continental Americas and the second-largest settlement in Belize, behind the former capital Belize City. Founded as a planned community in 1970, it is one of the newest national capital cities in the world."},"cr":{"t":"San_José,_Costa_Rica","x":"San José is the capital and largest city of Costa Rica, and the capital of San José Province. It is in the center of the country, in the mid-west of the Central Valley. San José is Costa Rica's seat of national government, focal point of political and economic activity, and major transportation hub."},"kn":{"t":"Basseterre","x":"Basseterre is the capital and largest city of Saint Kitts and Nevis with an estimated population of 14,000 in 2018. Geographically, the Basseterre port is located at 17°18′N 62°44′W, on the south-western coast of Saint Kitts Island, and it is one of the chief commercial depots of the Leeward Islands."},"to":{"t":"Nukuʻalofa","x":"Nukuʻalofa is the capital and largest city of Tonga. It is located on the north coast of the island of Tongatapu, in the country's southernmost island group. It is the world's westernmost capital of a sovereign state."},"ai":{"t":"The_Valley,_Anguilla","x":"The Valley is the capital of Anguilla, one of its fourteen districts, and the main town on the island. As of 2011, it had a population of 3,269."},"ms":{"t":"Plymouth,_Montserrat","x":"Plymouth is a ghost town and the de jure capital of the island of Montserrat, an overseas territory of the United Kingdom located in the Leeward Island chain of the Lesser Antilles, West Indies. It is the only ghost town that is the capital of a political territory."},"tc":{"t":"Cockburn_Town","x":"Cockburn Town is the capital of the Turks and Caicos Islands, spreading across most of Grand Turk. It was founded in 1681 by salt collectors."},"vg":{"t":"Road_Town","x":"Road Town, located on Tortola, is the capital and largest town of the British Virgin Islands. It is situated on the horseshoe-shaped Road Harbour in the centre of the island's south coast. The population was about 15,000 in 2018."},"vi":{"t":"Charlotte_Amalie,_U.S._Virgin_Islands","x":"Charlotte Amalie, on Saint Thomas, is the capital and largest town of the U.S. Virgin Islands. It is on the island's southern shore at the head of Charlotte Amalie Harbor. The town is known for its historic sites, Danish colonial architecture, harbor, and shopping."},"gg":{"t":"Saint_Peter_Port","x":"St. Peter Port is a town and one of the ten parishes on the island of Guernsey in the Channel Islands. It is the capital of the Bailiwick of Guernsey as well as the main port. The population in 2021 was 19,295."},"cx":{"t":"Flying_Fish_Cove","x":"Flying Fish Cove is the capital city and main settlement of Christmas Island. Although it was originally named after the British survey-ship Flying Fish, many maps simply label it \"The Settlement\". It was the first British settlement on the island, established in 1888."},"bl":{"t":"Gustavia","x":"Gustavia is the main town and capital of the island of Saint Barthélemy. Originally called Le Carénage, it was renamed in honor of King Gustav III of Sweden."},"sx":{"t":"Philipsburg,_Sint_Maarten","x":"Philipsburg is the main town and capital of Sint Maarten, a constituent country of the Kingdom of the Netherlands. It is located on the southern coast of Saint Martin island, between Great Bay and the Great Salt Pond. It serves as the main port of entry, with the major airport and port located in the vicinity."},"wf":{"t":"Mata_Utu","x":"Mata Utu is the capital city of Wallis and Futuna, an overseas collectivity of France. It is located on the island of Uvéa (ʻUvea), in the district of Hahake, of which it is also the capital. It is one of two ports in Wallis and Futuna, the other being at Leava on Futuna."},"xd":{"t":"Episkopi_Cantonment","x":"Episkopi Cantonment is the capital of Akrotiri and Dhekelia, a British overseas territory on the island of Cyprus, administered as a military base. It is located in the northwestern part of the Western Sovereign Base Area (Akrotiri), one of the two areas which comprise the territory."},"pr":{"t":"San_Juan,_Puerto_Rico","x":"San Juan is the capital city and most populous municipality in Puerto Rico, an unincorporated territory and insular area of the United States. San Juan was founded by Spanish imperialists in 1521, who called it Ciudad de Puerto Rico."},"pf":{"t":"Papeete","x":"Papeete is the capital city of French Polynesia, an overseas collectivity of the French Republic located in the Pacific Ocean. The commune of Papeʻete is located on the island of Tahiti, in the administrative subdivision of the Windward Islands, of which Papeʻete is the administrative capital."},"eh":{"t":"Laayoune","x":"Laayoune or El Aaiún is the largest city of the disputed territory of Western Sahara, with a population of 262,791 in 2024. The city is the de jure capital of the Sahrawi Arab Democratic Republic, though it is under de facto Moroccan administration as occupied territory."},"krd":{"t":"Erbil","x":"Erbil, also called Hawler, is the capital and most populated city in the Kurdistan Region of Iraq and the capital of the Erbil Governorate. Erbil is described as the region's cultural, economic, industrial, educational and medical hub."},"sml":{"t":"Hargeisa","x":"Hargeisa is the capital and largest city of the Republic of Somaliland, a partially recognised sovereign state in the Horn of Africa, still considered internationally to be part of Somalia. It is also the regional capital of the Maroodi Jeex region of Somaliland."},"abk":{"t":"Sukhumi","x":"Sukhumi or Sokhumi is a city in a wide bay on the Black Sea's eastern coast. It is both the capital and largest city of Abkhazia, a partially recognized state that most countries consider a part of Georgia. The city has been controlled by Abkhazia since the Abkhazian war in 1992–93."},"gl":{"t":"Nuuk","x":"Nuuk is the capital and most populous city of Greenland, an autonomous territory of Denmark. It is the seat of the Sermersooq municipality and the government of Greenland and is the territory's largest cultural and economic center."},"gu":{"t":"Hagåtña,_Guam","x":"Hagåtña, formerly Agana or Agaña, is a coastal village and the capital of the United States territory of Guam. The settlement is on the west coast of Guam at the mouth of the Hagåtña River. It had a population of 943 people as of the 2020 census."},"bm":{"t":"Hamilton,_Bermuda","x":"Hamilton is the capital city of the British Overseas Territory of Bermuda, and the main settlement of Pembroke Parish. A port city, Hamilton is Bermuda's financial and commercial centre, and a popular tourist destination. Its population of 854 (2016) and its small land area make it one of the smallest capital cities in the world."},"fk":{"t":"Stanley,_Falkland_Islands","x":"Stanley is the capital city of the Falkland Islands. It is located on the island of East Falkland, on a north-facing slope in one of the wettest parts of the islands."},"re":{"t":"Saint-Denis,_Réunion","x":"Saint-Denis, unofficially Saint-Denis de La Réunion for disambiguation, is the prefecture of the French overseas department and region of Réunion, in the Indian Ocean. It is located at the island's northernmost point, close to the mouth of the Rivière Saint-Denis."},"je":{"t":"St_Helier","x":"St Helier is the capital of Jersey, the largest of the Channel Islands in the English Channel. It is the most populous of the twelve parishes of Jersey, with a population of 35,822, over one-third of the island's total population. The town of St Helier is the largest settlement and only town of Jersey."},"bf":{"t":"Ouagadougou","x":"Ouagadougou or Wagadugu is the capital and largest city of Burkina Faso, and the administrative, communications, cultural and economic centre of the nation. It had a population of 2,415,266 in 2019. The city's name is often shortened to Ouaga. The inhabitants are called ouagalais."},"td":{"t":"N'Djamena","x":"N'Djamena is the capital and largest city of Chad. It is also a Special Status Province, divided into 10 districts or arrondissements."},"kw":{"t":"Kuwait_City","x":"Kuwait City is the capital and largest city of Kuwait. Located at the heart of the country on the south shore of Kuwait Bay on the Persian Gulf, it is the political, cultural and economic primate city of the emirate, being home to the headquarters of most Kuwaiti corporations and the entirety of its banking system."},"gd":{"t":"St._George's,_Grenada","x":"St. George's is the capital and largest city of Grenada. The city is surrounded by a hillside of an old volcano crater and is located on a horseshoe-shaped harbour. It is on the southwest coast of the island and its main port."},"fm":{"t":"Palikir","x":"Palikir is the capital city of the Federated States of Micronesia located in the western Pacific Ocean. A town of slightly above 5,000 residents, it is part of the larger Sokehs municipality, which had a population of 6,964 as of 2024, out of the nation's total population of 106,487."},"ws":{"t":"Apia","x":"Apia is the capital and largest city of Samoa. It is located on the central north coast of Upolu, Samoa's second-largest island. Apia falls within the political district (itūmālō) of Tuamasaga."},"sh":{"t":"Jamestown,_Saint_Helena","x":"Jamestown is the capital city of the British Overseas Territory of Saint Helena, Ascension and Tristan da Cunha, located on the island of Saint Helena in the South Atlantic Ocean. It is also the historic main settlement of the island and is on its north-western coast."},"mf":{"t":"Marigot,_Saint_Martin","x":"Marigot is the main town and capital in the French Collectivity of Saint Martin. The area has been inhabited since the 17th century and fortifications were erected in 1789. The population has been in decline for decades."},"sos":{"t":"Tskhinvali","x":"Tskhinvali or Tskhinval, occasionally called Stalinir during specific contexts, is the capital of the disputed de facto independent Republic of South Ossetia, internationally considered part of Shida Kartli, Georgia. Tskhinvali Region was also known historically as Samachablo by Georgians."},"fo":{"t":"Tórshavn","x":"Tórshavn, locally referred to as Havn, is the capital and largest city of the Faroe Islands. It is located in the southern part on the east coast of Streymoy. To the northwest of the city lies the 347-meter-high (1,138 ft) mountain Húsareyn, and to the southwest, the 350-meter-high (1,150 ft) Kirkjubøreyn."}};
